<?php
require_once 'custom/HrDocumentSupport.php';require_once '/opt/hr/HrUi.php';
$bean=BeanFactory::newBean('HR_People');if(!$bean->ACLAccess('list')){http_response_code(403);die('Нет доступа к сотрудникам');}
$q=is_string($_GET['q']??null)?trim($_GET['q']):'';$where=$q!==''?'hr_people.name LIKE '.$GLOBALS['db']->quoted('%'.$q.'%'):'';$people=$bean->get_list('name',$where,0,50,50)['list'];$history=hrUiHistory();if($q!=='')$history=array_values(array_filter($history,fn($item)=>mb_stripos($item['person_name'],$q)!==false));
?><!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Документы сотрудников</title><?php hrUiStyle();?><body class="hr-page"><main class="hr-shell"><?php hrUiNav('documents');?><h1>Документы сотрудников</h1><p class="hr-muted">Выберите человека для генерации или откройте готовый документ. <a href="<?=hrUiEscape(hrUiGuide('documents'))?>">Пошаговая инструкция</a></p>
<?php if($bean->ACLAccess('edit')):?><div class="hr-actions"><a class="hr-button" href="<?=hrUiEscape(hrUiUrl('HrBatch'))?>">Создать документы для нескольких сотрудников</a></div><?php endif?>
<form method="get" class="hr-panel"><input type="hidden" name="entryPoint" value="HrLibrary"><label>Поиск по ФИО <input name="q" value="<?=hrUiEscape($q)?>" placeholder="Введите фамилию"></label><div class="hr-actions"><button>Найти</button><a href="<?=hrUiEscape(hrUiUrl('HrLibrary'))?>">Сбросить поиск</a></div></form>
<div class="hr-grid"><?php foreach($people as $person):if(!$person->ACLAccess('view'))continue;?><section class="hr-panel"><h3><?=hrUiEscape($person->name)?></h3><p class="hr-muted"><?=hrUiEscape($person->position)?></p><a class="hr-button" href="<?=hrUiEscape(hrUiUrl('HrDocuments',['person'=>$person->id]))?>"><?=$person->ACLAccess('edit')?'Сформировать документ':'Посмотреть документы'?></a></section><?php endforeach?></div>
<?php if(!$people):?><p class="hr-empty">Сотрудники не найдены. Измените запрос или создайте карточку сотрудника.</p><?php endif?><section class="hr-panel"><h2>Последние документы</h2><?php hrUiHistoryTable(array_slice($history,0,30));?></section></main></body></html>
